const beat = (key, label, type, spoilerLevel, stage, classification, revealText, revealSubtext) => ({
  key, label, type, spoilerLevel, stage, classification, revealText, revealSubtext,
});

const makeGraph = ({ id, title, summary, twistType, sources, beats, links }) => {
  const nodes = [
    { id, label: title, graphLabel: title, type: 'film', spoilerLevel: 0, size: 9, revealText: `Story map: ${title}`, revealSubtext: summary, revealClassification: 'Film Hub' },
    ...beats.map((item, index) => ({
      id: `${id}-${item.key}`,
      label: item.label,
      graphLabel: item.graphLabel || item.label,
      type: item.type,
      spoilerLevel: item.spoilerLevel,
      size: item.type === 'twist' ? 8 : item.type === 'character' ? 5.5 : 4.5,
      revealText: item.revealText,
      revealSubtext: item.revealSubtext,
      revealClassification: item.classification,
      timelineOrder: index + 1,
      timelineStage: item.stage,
      sources,
    })),
  ];
  const nodeId = key => key === 'film' ? id : `${id}-${key}`;
  return {
    nodes,
    links: links.map(([from, to, relationship, explanation, spoilerLevel = 1]) => ({
      source: nodeId(from), target: nodeId(to), film: id, relationship, explanation, spoilerLevel,
    })),
    twistType,
  };
};

